let isDemo=true,fb={},currentUser=null,currentPage='dashboard',db={users:[],leads:[],followups:[],quotations:[],installations:[],payments:[],history:[]},selectedFilter='',searchText='',busy=false,leadImportRows=null,leadImportReady=false;
const requestedDemo=new URLSearchParams(window.location.search).get('demo')==='1';
