function openFollowup(existing){let f=existing||{};let opts=choiceLeads();if(!opts.length){toast('Create a lead first.',true);goPage('leads');return}openModal(existing?'Update follow-up':'Schedule follow-up','Calls, WhatsApp, meetings and site visits',`${existing?`<div class="full">${esc(leadOf(f.leadId)?.customerName||'')}</div>`:formLead()}${select('type','Activity type',['Phone Call','WhatsApp','Site Visit','Customer Meeting','Email','Other'],f.type||'Phone Call')}${input('dueDate','Scheduled date',f.dueDate||today(),'date',true)}${select('status','Activity status',['Pending','Completed'],f.status||'Pending')}${textarea('notes','Notes or next action',f.notes||'')}`,async x=>{let leadId=existing?.leadId||x.leadId,l=leadOf(leadId);const d={leadId,assignedTo:l.assignedTo,type:x.type,dueDate:x.dueDate,status:x.status,notes:x.notes};if(!existing){d.createdAt=stamp();d.createdBy=uid()}await writeRecord('followups',d,existing?.id);if(x.status==='Pending'&&(!l.nextFollowUp||x.dueDate<l.nextFollowUp))await writeRecord('leads',{nextFollowUp:x.dueDate,updatedAt:stamp()},leadId)},existing?{recordType:'followup',recordId:existing.id}:null)}
function openQuote(existing){let q=existing||{},opts=choiceLeads();if(!opts.length){toast('Create a lead first.',true);return}openModal(existing?'Edit quotation':'Create solar quotation','Commercial proposal, solar system type and status',`${existing?`<div class="full">${esc(leadOf(q.leadId)?.customerName||'')}</div>`:formLead()}${select('systemType','System type',['On-grid','Hybrid','Off-grid'],q.systemType||'On-grid')}${input('capacityKw','Capacity (kWp)',q.capacityKw||'','number',true,'min="0.1" step="0.1"')}${input('price','Quoted project value (₹)',q.price||'','number',true,'min="0"')}${select('status','Quotation status',QUOTESTATUS,q.status||'Draft')}${input('validUntil','Valid until',q.validUntil||isoOffset(14),'date')}${textarea('notes','Scope / inclusions',q.notes||'')}`,async x=>{let leadId=existing?.leadId||x.leadId,l=leadOf(leadId);const data={leadId,assignedTo:l.assignedTo,systemType:x.systemType,capacityKw:num(x.capacityKw),price:num(x.price),status:x.status,validUntil:x.validUntil,notes:x.notes,updatedAt:stamp()};if(!existing){data.createdBy=uid();data.createdAt=stamp()}await writeRecord('quotations',data,existing?.id);if(x.status==='Accepted'&&l.stage!=='Won')await writeRecord('leads',{stage:'Won',updatedAt:stamp()},leadId);else if(['Sent','Revised'].includes(x.status)&&!['Won','Lost'].includes(l.stage))await writeRecord('leads',{stage:x.status==='Sent'?'Quotation Sent':'Negotiation',updatedAt:stamp()},leadId)},existing?{recordType:'quotation',recordId:existing.id}:null)}
