function openTeam(existing){const team=currentPage==='salesTeam'?'sales':'project',roles=teamRoles(team),member=memberRole(team);if(!canManageTeam(team)||existing&&(!roles.includes(existing.role)||!businessManager()&&existing.role!==member))return;const options=(businessManager()?roles:[member]).map(role=>({id:role,name:roleLabel(role)}));let u=existing||{};openModal(existing?'Manage team member':'Add team member',`Add or deactivate ${team==='sales'?'sales people':'project executives'} using their Firebase Authentication UID`,`${input('id','Firebase Authentication UID',u.id||'','text',true,existing?'readonly':'')}${input('name','Employee name',u.name||'','text',true)}${input('email','Login email',u.email||'','email',true)}${select('role','Team role',options,u.role||member)}${select('active','Account access',[{id:'true',name:'Active'},{id:'false',name:'Disabled'}],String(u.active??true))}`,async x=>{await upsertUser({name:x.name,email:x.email,role:x.role,active:x.active==='true'},x.id)})}
function csvExport(){const headers=['Customer','Mobile','City','Category','kWp','EB Bill','Lead source','Stage','Salesperson','Next follow-up','Quoted value','Notes'];const records=visible(db.leads).map(l=>[l.customerName,l.phone,l.city,l.category,l.capacityKw,l.monthlyBill,l.source,l.stage,personOf(l.assignedTo),l.nextFollowUp,amountOf(l),l.notes]);let csv=[headers,...records].map(row=>row.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');let blob=new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8;'}),url=URL.createObjectURL(blob);let a=document.createElement('a');a.href=url;a.download='MySolarDesk_Leads_'+today()+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),500)}
